	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	CONSTRAINT pk_evaluations PRIMARY KEY (id), 
	CONSTRAINT ck_evaluations_confidence_range CHECK (confidence IS NULL OR (confidence >= 0 AND confidence <= 1)), 
	CONSTRAINT fk_evaluations_transcript_course_id_transcript_courses FOREIGN KEY(transcript_course_id) REFERENCES transcript_courses (id), 
	CONSTRAINT fk_evaluations_syllabus_id_syllabi FOREIGN KEY(syllabus_id) REFERENCES syllabi (id), 
